/**
 * Fraunces 500, inlined as base64.
 *
 * It was fetched from Google Fonts at render time until a build failed because
 * that host was briefly unreachable: satori does not degrade without a font,
 * it throws "No fonts are loaded" and takes the deployment with it.
 *
 * Reading the .ttf from disk was the obvious fix and did not work. Next traces
 * new URL(..., import.meta.url) into the bundle, but the URL instance that
 * crosses the bundler boundary is not the one node:fs recognises, so readFile
 * rejects its own argument type. Rather than keep fighting the tracing layer
 * for a 70 KB file used by one route, the bytes live here: no fetch, no file
 * system, no path resolution, nothing left to fail.
 *
 * Fraunces is licensed under the Open Font License. To change the face,
 * regenerate this file from the .ttf rather than editing it.
 */
export const FRAUNCES_500_BASE64 =
  '';
